 groups:[['ज़मानत',['ज़मानतीय अपराधों में ज़मानत','मजिस्ट्रेट के समक्ष ज़मानत','सत्र न्यायालय एवं उच्च न्यायालय में ज़मानत','ज़मानत रद्द करने के आवेदन का विरोध']],['अग्रिम ज़मानत',['सत्र न्यायालय में आवेदन','पटना उच्च न्यायालय में आवेदन','गिरफ़्तारी से अंतरिम संरक्षण','ज़मानत शर्तों का अनुपालन']],['निरस्तीकरण (क्वैशिंग)',['प्राथमिकी का निरस्तीकरण','आरोप-पत्र एवं संज्ञान आदेश का निरस्तीकरण','समझौते के आधार पर निरस्तीकरण','अंतर्निहित शक्तियों के अंतर्गत याचिका']],['विचारण में बचाव',['उन्मोचन (डिस्चार्ज) आवेदन','आरोप विरचन','गवाहों से प्रति-परीक्षा','अंतिम बहस']],['अपील एवं पुनरीक्षण',['दोषसिद्धि के विरुद्ध अपील','आपराधिक पुनरीक्षण','सज़ा का निलंबन','दोषमुक्ति के विरुद्ध अपील']],['परिवाद वाद',['मजिस्ट्रेट के समक्ष परिवाद','प्रोटेस्ट पिटीशन','चेक अनादरण परिवाद','दहेज एवं वैवाहिक आपराधिक मामले']]],
