const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const icon=k=>`<svg viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round">${I[k]}</svg>`;
const sh=(label,title,sub)=>`<div class="sh"><div class="eyebrow">${label}</div><h2>${title}</h2><div class="rule"></div>${sub?`<p>${sub}</p>`:''}</div>`;
const faqList=f=>`<div class="faq">${f.map((q,i)=>`<details${i?'':' open'}><summary>${esc(q[0])}</summary><p>${esc(q[1])}</p></details>`).join('')}</div>`;
const WA='https://wa.me/916204166690';
const altURL=l=>U(CUR(),l);
const langToggle=id=>`<div class="lang" role="group" aria-label="Language / भाषा" id="${id}"><a href="${altURL('en')}" hreflang="en-IN" data-lang="en" aria-current="${LANG==='en'}">EN</a><a href="${altURL('hi')}" hreflang="hi-IN" data-lang="hi" aria-current="${LANG==='hi'}" lang="hi">हिंदी</a></div>`;

/* ---------- chrome: gate, util bar, header ---------- */
function renderChrome(){
 const x=t();
 const PRE=document.documentElement.hasAttribute('data-pre')&&!window.__CLC_RERENDER;
 if(!PRE)$('#gate').innerHTML=`<div class="gate-in"><div class="gate-head"><div class="mark"><span>CLC</span></div><div style="flex:1"><b>${x.brand}</b><small>${x.brandShort}</small></div>${langToggle('lg-gate')}</div>
 <div class="gate-body"><h2 id="gate-h">${x.gateH}</h2><p>${x.gate1}</p><p>${x.gate2}</p>
 <label class="ck"><input type="checkbox" id="gate-ck"> ${x.gateCk}</label>
 <button class="btn btn-navy" id="gate-go" type="button" disabled>${x.gateGo}</button></div></div>`;
 $('#gate-ck').addEventListener('change',e=>$('#gate-go').disabled=!e.target.checked);
 $('#gate-go').addEventListener('click',()=>{try{sessionStorage.setItem('clc-gate','1')}catch(e){}$('#gate').hidden=true;document.body.style.overflow=''});
 if(!PRE)$('#hdr').innerHTML=`<div class="wrap nav">
  <a class="brand" href="${U('home')}"><div class="mark"><span>CLC</span></div><div><b>${x.brand}</b><small>${x.brandSub}</small></div></a>
  <div class="nav-r">${langToggle('lg-hdr')}
  <button class="menu-btn" id="menu" type="button" aria-expanded="false" aria-controls="links" aria-label="${x.menu}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M3 7h18M3 12h18M3 17h18"/></svg></button></div>
  <nav class="links" id="links">
   <a href="${U('home')}" data-nav="home">${x.nav.home}</a><a href="${HOMEA('about')}" data-nav="about">${x.nav.about}</a>
   <div class="dd" id="dd"><button type="button" id="dd-btn" aria-expanded="false">${x.nav.practice} ▾</button><div class="dd-menu" id="dd-menu">${ORDER.map(k=>`<a href="${U(k)}">${P(k).title}<span>›</span></a>`).join('')}</div></div>
   <a href="${HOMEA('founder')}" data-nav="founder">${x.nav.founder}</a><a href="${U('contact')}" data-nav="contact"${CUR()==='contact'?' aria-current="page"':''}>${x.nav.contact}</a>
   <a class="btn btn-gold" href="#chambers">${x.nav.book}</a></nav></div>`;
 $('#dd-btn').addEventListener('click',e=>{e.stopPropagation();const o=$('#dd').classList.toggle('open');$('#dd-btn').setAttribute('aria-expanded',o)});
 $('#menu').addEventListener('click',()=>{const o=$('#links').classList.toggle('open');$('#menu').setAttribute('aria-expanded',o)});
 document.querySelectorAll('.lang a').forEach(b=>b.addEventListener('click',()=>{try{localStorage.setItem('clc-lang',b.dataset.lang)}catch(e){}}));
}
function setLang(l){
 if(l===LANG)return;LANG=l;try{localStorage.setItem('clc-lang',l)}catch(e){}
 document.documentElement.lang=l;const y=scrollY;const ck=$('#gate-ck')&&$('#gate-ck').checked;
 renderChrome();if(ck){$('#gate-ck').checked=true;$('#gate-go').disabled=false}
 current=null;route(true);scrollTo({top:y,behavior:'instant'});
}

