function bailBlock(){const b=t().bail;return `<section class="s"><div class="wrap">${sh(b.eye,b.h,b.sub)}
<div class="tbl sec"><table><thead><tr>${b.th.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${b.rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="note">${b.note}</p></div></section>`}

function journeyBlock(){const j=t().jr;
 const lab=i=>i===4?[j.allowed,j.rejected]:[j.yes,j.no];
 return `<section class="s" id="journey"><div class="wrap">${sh(j.eye,j.h,j.sub)}
 <div class="journey">${j.steps.map((s,i)=>`<div class="jstep"><div class="jnum">${i+1}</div><div><h3>${s[0]}</h3><p>${s[1]}</p>${s[2]?`<div class="fork" role="group" aria-label="${esc(s[0])}"><button type="button" aria-pressed="true" data-j="${i}" data-v="0">${lab(i)[0]}</button><button type="button" aria-pressed="false" data-j="${i}" data-v="1">${lab(i)[1]}</button></div><div class="branch" id="br-${i}"><b>${lab(i)[0]}</b>${s[2][0]}</div>`:''}</div></div>`).join('')}
 <div class="jstep end"><div class="jnum">✓</div><div><h3>${j.end[0]}</h3><p>${j.end[1]}</p></div></div></div>
 <p class="note">${j.note}</p></div></section>`}
function journeyWire(){const j=t().jr;
 document.querySelectorAll('.fork button').forEach(b=>b.addEventListener('click',()=>{
  const i=+b.dataset.j,v=+b.dataset.v;
  b.parentNode.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));
  $('#br-'+i).innerHTML=`<b>${esc(b.textContent)}</b>${j.steps[i][2][v]}`;
 }))}

function remCard(r,k){return `<article class="rem"><h3>${r.t}</h3><div class="law">${r.law}</div>
<div class="tabs" role="tablist">${t().tabs.map((n,i)=>`<button type="button" role="tab" aria-selected="${!i}" data-k="${k}" data-i="${i}">${n}</button>`).join('')}</div>
<div class="panel" id="pn-${k}"><p>${r.o}</p></div><div class="fit"><b>${t().fit}</b>${r.fit}</div></article>`}
function recoveryBlock(){const x=t(),R=REM[LANG];let k=0;
 return `<section class="s" id="prevent"><div class="wrap">${sh(x.prev.eye,x.prev.h,x.prev.sub)}
 <div class="prev">${x.prev.items.map((p,i)=>`<article><span class="n">${i+1}</span><h3>${p[0]}</h3><p>${p[1]}</p><details><summary>${x.prev.view}</summary><div class="kv"><div><h5>${x.prev.ke}</h5><ul>${p[2].map(v=>`<li>${v}</li>`).join('')}</ul></div><div><h5>${x.prev.docs}</h5><ul>${p[3].map(v=>`<li>${v}</li>`).join('')}</ul></div></div></details></article>`).join('')}</div></div></section>
 <section class="s"><div class="wrap">${sh(x.remCiv.eye,x.remCiv.h,x.remCiv.sub)}<div class="remedies two">${R.civil.map(r=>remCard(r,'c'+(k++))).join('')}</div></div></section>
 <section class="s"><div class="wrap">${sh(x.remCri.eye,x.remCri.h,x.remCri.sub)}<div class="remedies">${R.criminal.map(r=>remCard(r,'c'+(k++))).join('')}</div></div></section>`}
function recoveryWire(){const all=[...REM[LANG].civil,...REM[LANG].criminal];
 document.querySelectorAll('.rem .tabs button').forEach(b=>b.addEventListener('click',()=>{
  const r=all[+b.dataset.k.slice(1)],i=+b.dataset.i;
  b.parentNode.querySelectorAll('button').forEach(x=>x.setAttribute('aria-selected',x===b));
  $('#pn-'+b.dataset.k).innerHTML=i===0?`<p>${r.o}</p>`:i===1?`<ol>${r.p.map(x=>`<li>${x}</li>`).join('')}</ol>`:`<ul>${(i===2?r.b:r.d).map(x=>`<li>${x}</li>`).join('')}</ul>`;
 }))}

function willBlock(){const w=t().will;return `<section class="s"><div class="wrap">${sh(w.eye,w.h,w.sub)}
<div class="match"><div class="col"><h5>${w.a}</h5><ul id="wa">${w.assets.map((a,i)=>`<li><button type="button" data-a="${i}">${a}</button></li>`).join('')}</ul></div>
<svg id="wl" viewBox="0 0 140 320" preserveAspectRatio="none" aria-hidden="true"></svg>
<div class="col"><h5>${w.b}</h5><ul id="wb">${w.bens.map(b=>`<li><button type="button" tabindex="-1">${b}</button></li>`).join('')}</ul></div></div>
<p class="match-cap">${w.cap}</p></div></section>`}
function willWire(){
 const M=[[0,1],[1],[0,2],[1,3],[1,4]];
 const draw=a=>{
  const A=[...document.querySelectorAll('#wa button')],B=[...document.querySelectorAll('#wb button')],svg=$('#wl');
  A.forEach((x,i)=>x.classList.toggle('on',i===a));B.forEach((x,i)=>x.classList.toggle('on',M[a].includes(i)));
  const r=svg.getBoundingClientRect(),sc=320/(r.height||320);
  const y=el=>((el.getBoundingClientRect().top+el.getBoundingClientRect().height/2)-r.top)*sc;
  svg.innerHTML=M[a].map(j=>`<path d="M0 ${y(A[a])} C70 ${y(A[a])} 70 ${y(B[j])} 140 ${y(B[j])}" fill="none" stroke="currentColor" stroke-width="1.2" vector-effect="non-scaling-stroke"/>`).join('');
 };
 document.querySelectorAll('#wa button').forEach(b=>b.addEventListener('click',()=>draw(+b.dataset.a)));
 requestAnimationFrame(()=>draw(0));
}

function tableBlock(b){return `<section class="s"><div class="wrap">${sh(b.eye,b.h,b.sub)}
<div class="tbl"><table><thead><tr>${b.th.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${b.rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="note">${b.note}</p></div></section>`}
function timelineBlock(j){return `<section class="s"><div class="wrap">${sh(j.eye,j.h,j.sub)}
<div class="journey">${j.steps.map((s,i)=>`<div class="jstep${i===j.steps.length-1?' end':''}"><div class="jnum">${i===j.steps.length-1?'✓':i+1}</div><div><h3>${s[0]}</h3><p>${s[1]}</p></div></div>`).join('')}</div>
<p class="note">${j.note}</p></div></section>`}
