function wireCommon(){const x=t();
 document.querySelectorAll('.copy').forEach(b=>b.addEventListener('click',()=>{
  const el=document.getElementById(b.dataset.copy),v=el.textContent;
  const sel=()=>{const r=document.createRange();r.selectNodeContents(el);const s=getSelection();s.removeAllRanges();s.addRange(r);b.textContent=x.selected};
  (navigator.clipboard?navigator.clipboard.writeText(v).then(()=>b.textContent=x.copied,sel):sel());
  setTimeout(()=>b.textContent=x.copy,1800);
 }));
 const f=$('#intake');if(f)f.addEventListener('submit',e=>{e.preventDefault();
  const v=id=>$(id).value.trim(),n=v('#q-name'),p=v('#q-phone'),a=$('#q-ack').checked,err=$('#q-err');
  if(!n||!/^[0-9+\s-]{10,15}$/.test(p)||!a){err.textContent=x.fmErr;err.style.color='var(--gold)';return}
  err.textContent=x.fmReq;err.style.color='';
  const lines=[`*${x.waHead}*`,'',`${x.waN}: ${n}`,`${x.waP}: ${p}`,`${x.waT}: ${v('#q-topic')}`];
  if(v('#q-court'))lines.push(`${x.waC}: ${v('#q-court')}`);
  if(v('#q-msg'))lines.push('',`${x.waM}: ${v('#q-msg')}`);
  const url=WA+'?text='+encodeURIComponent(lines.join('\n'));
  let w=null;try{w=window.open(url,'_blank','noopener')}catch(_){}
  let box=$('#q-done');if(!box){box=document.createElement('div');box.id='q-done';box.className='ok';f.appendChild(box)}
  box.innerHTML=`<p style="margin:0 0 12px">${x.fmOk}</p><div style="display:flex;gap:10px;flex-wrap:wrap"><a class="btn btn-wa" style="width:auto;margin:0" href="${url}" target="_blank" rel="noopener">${icon('wa')}${x.fmOpen}</a><button type="button" class="btn btn-outline" id="q-edit">${x.fmEdit}</button></div>`;
  f.querySelectorAll('.f,.ck,.ff,.sub').forEach(el=>el.hidden=true);
  $('#q-edit').addEventListener('click',()=>{f.querySelectorAll('.f,.ck,.ff,.sub').forEach(el=>el.hidden=false);box.remove()});
 });
}

/* ---------- routing ---------- */
const KEY_BY_SLUG=Object.fromEntries(Object.entries(SLUG).map(([k,v])=>[v,k]));
function CUR(){const seg=location.pathname.replace(/^\/hi(\/|$)/,'/').split('/').filter(Boolean)[0]||'';return KEY_BY_SLUG[seg]||'home'}
// old single-page links such as clclegal.in/#criminal now live at their own URL
(function(){const h=location.hash.slice(1);if(SLUG[h])location.replace(U(h)+(location.search||''))})();
let current=null;
function route(){
 const page=CUR();
 current=page;
 if(!(document.documentElement.hasAttribute('data-pre')&&$('#app').children.length))$('#app').innerHTML=(page==='home'?home():page==='contact'?contactPage():practice(page))+footer();
 wireCommon();
 if(page==='mutation')journeyWire();
 if(page==='recovery')recoveryWire();
 if(page==='succession')willWire();
 navState();
 const h=location.hash.slice(1);if(h){const el=document.getElementById(h);if(el)requestAnimationFrame(()=>el.scrollIntoView())}
}
function navState(){const h=location.hash.slice(1);document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('on',(CUR()==='home'&&a.dataset.nav===(h||'home'))||(CUR()==='contact'&&a.dataset.nav==='contact')));
 const L=$('#links');if(L){L.classList.remove('open');$('#menu').setAttribute('aria-expanded','false');$('#dd').classList.remove('open')}}
document.addEventListener('click',e=>{const d=$('#dd');if(d&&!d.contains(e.target))d.classList.remove('open')});
addEventListener('hashchange',navState);

document.documentElement.lang=LANG;
renderChrome();
(function(){let ok=false;try{ok=sessionStorage.getItem('clc-gate')==='1'}catch(e){}
 if(ok)$('#gate').hidden=true;else document.body.style.overflow='hidden'})();
route();


